window.docContents[184].resolve({"/Terms-and-Sorts/#Cvc___lean----High-Level-CVC5-API--Terms-and-Sorts":{"contents":"Cvc.lean exposes two API-s for terms: Typed and Untyped.\n\nA cvc5 term.\n\nTyped terms have a type parameter for the actual type of that term.\n\nA boolean literal.\n\nBinary conjunction.\n\nAn integer literal.\n\nBinary addition.\n\nA cvc5 term.\n\nAs their path implies, untyped terms are just terms\n\n\n","context":"Cvc.lean -- High-Level CVC5 API","header":"2. Terms and Sorts","id":"/Terms-and-Sorts/#Cvc___lean----High-Level-CVC5-API--Terms-and-Sorts"}});